/* ViewImage-compatible local lightbox. Based on ViewImage.js 2.0.2 (MIT). */
(() => {
  const ViewImage = {
    target: "[view-image] img",
    init(target) {
      if (target) this.target = target
      // Capture the click before Quartz SPA/navigation handlers can consume it.
      document.removeEventListener("click", this.listener, true)
      document.addEventListener("click", this.listener, true)
    },
    listener(event) {
      if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return
      const selector = ViewImage.target
        .split(",")
        .map((item) => `${item.trim()}:not([no-view]):not([data-no-lightbox]):not([atk-emoticon]):not(.comments-emoticon)`)
        .join(",")
      if (!(event.target instanceof Element)) return
      const image = event.target.closest(selector)
      if (!image) return
      const scope = image.closest("[view-image]") || document.body
      const images = [...scope.querySelectorAll(selector)].map((item) => item.href || item.src)
      event.preventDefault()
      event.stopPropagation()
      ViewImage.display(images, image.href || image.src)
    },
    display(images, current) {
      let index = Math.max(0, images.indexOf(current))
      const overlay = document.createElement("dialog")
      overlay.className = "view-image"
      overlay.setAttribute("aria-label","图片预览")
      overlay.tabIndex=-1
      overlay.innerHTML = `
        <style>
          .view-image{position:fixed;inset:0;z-index:500;padding:1rem;margin:0;box-sizing:border-box;width:100dvw;height:100dvh;max-width:none;max-height:none;border:0;background:transparent;overscroll-behavior:contain;touch-action:none;display:flex;flex-direction:column;animation:view-image-in 300ms;backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}
          .view-image::backdrop{background:transparent}.view-image__out{animation:view-image-out 300ms forwards}@keyframes view-image-in{from{opacity:0}}@keyframes view-image-out{to{opacity:0}}
          .view-image-close__full{position:absolute;inset:0;background:rgba(48,55,66,.3);cursor:zoom-out}.view-image-container{height:0;min-width:0;flex:1;display:grid;grid-template:minmax(0,1fr)/minmax(0,1fr);place-items:center;overflow:hidden}.view-image-lead{display:contents}.view-image-lead img{grid-area:1/1;min-width:0;min-height:0;position:relative;z-index:1;max-width:100%;max-height:100%;object-fit:contain;border-radius:3px;animation:view-image-lead-in 300ms}@keyframes view-image-lead-in{from{opacity:0;transform:translateY(-20px)}}
          .view-image-tools{position:absolute;bottom:5%;left:1rem;right:1rem;z-index:1;display:flex;justify-content:space-between;align-content:center;max-width:600px;margin:0 auto;padding:10px;border-radius:5px;background:rgba(0,0,0,.1);backdrop-filter:blur(10px);color:#fff}.view-image-btn{width:32px;height:32px;display:flex;justify-content:center;align-items:center;cursor:pointer;border:0;border-radius:3px;background-color:rgba(255,255,255,.2);padding:0}.view-image-btn:hover{background-color:rgba(255,255,255,.5)}.view-image-tools__count{width:60px;display:flex;align-items:center;justify-content:center}.view-image-tools__flip{display:flex;gap:10px}.view-image-tools [class*=-close]{margin:0 10px}
        </style>
        <div class="view-image-container"><div class="view-image-lead"></div><div class="view-image-close view-image-close__full"></div></div>
        <div class="view-image-tools"><div class="view-image-tools__count"><span><b class="view-image-index"></b>/${images.length}</span></div><div class="view-image-tools__flip"><button class="view-image-btn view-image-tools__flip-prev" aria-label="上一张"><svg width="20" height="20" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M31 36L19 24L31 12" stroke="white" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button class="view-image-btn view-image-tools__flip-next" aria-label="下一张"><svg width="20" height="20" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M19 12L31 24L19 36" stroke="white" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div><button class="view-image-btn view-image-close" aria-label="关闭"><svg width="16" height="16" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M8 8L40 40M8 40L40 8" stroke="white" stroke-width="4" stroke-linecap="round"/></svg></button></div>`
      const lead = overlay.querySelector(".view-image-lead")
      let activeImage, scale = 1, offsetX = 0, offsetY = 0
      let gesture, suppressClickUntil = 0, switching = false, motion, neighborMotion, neighbor, neighborDirection
      const reducedMotion = () => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
      const container = overlay.querySelector(".view-image-container")
      const clamp = (value, limit) => Math.max(-limit, Math.min(limit, value))
      const renderTransform = () => {
        if (!activeImage) return
        const box = container.getBoundingClientRect()
        offsetX = clamp(offsetX, Math.max(0, (activeImage.clientWidth * scale - box.width) / 2))
        offsetY = clamp(offsetY, Math.max(0, (activeImage.clientHeight * scale - box.height) / 2))
        activeImage.style.animation = "none"
        activeImage.style.transform = `translate(${offsetX}px, ${offsetY}px) scale(${scale})`
      }
      const clearNeighbor = () => { neighborMotion?.cancel(); neighborMotion = undefined; neighbor?.remove(); neighbor = undefined }
      const setImage = (prepared) => {
        motion?.cancel(); motion = undefined; switching = false
        clearNeighbor()
        scale = 1; offsetX = offsetY = 0; gesture = undefined
        lead.innerHTML = ""
        const image = prepared || new Image()
        activeImage = image
        if (!prepared) image.src = images[index]
        else { image.style.transform = "none"; image.style.animation = "none" }
        image.alt = "ViewImage"
        image.setAttribute("no-view", "")
        lead.append(image)
        overlay.querySelector(".view-image-index").textContent = index + 1
      }
      let closing = false,removed=false
      const remove=()=>{
        if(removed)return
        removed=true
        motion?.cancel(); clearNeighbor()
        document.removeEventListener("keydown",keyboard)
        if(overlay.open)overlay.close()
        overlay.remove()
        document.dispatchEvent(new CustomEvent("view-image-close",{detail:{overlay}}))
      }
      const close = () => {
        if (closing) return
        closing = true
        document.removeEventListener("keydown", keyboard)
        // Retain modal interaction blocking through the closing animation.
        overlay.classList.add("view-image__out")
        const fallback = window.setTimeout(remove, 400)
        overlay.addEventListener("animationend", event => {
          if (event.target !== overlay) return
          window.clearTimeout(fallback)
          remove()
        })
      }
      const keyboard = (event) => {
        if (event.key === "Escape") close()
        if (event.key === "ArrowLeft") { index = (index + images.length - 1) % images.length; setImage() }
        if (event.key === "ArrowRight") { index = (index + 1) % images.length; setImage() }
      }
      const prepareNeighbor = dx => {
        const direction = dx < 0 ? -1 : 1
        if (neighbor && neighborDirection === direction) return neighbor
        clearNeighbor()
        neighborDirection = direction
        neighbor = new Image()
        neighbor.src = images[(index + (dx < 0 ? 1 : -1) + images.length) % images.length]
        neighbor.alt = "ViewImage"
        neighbor.setAttribute("no-view", "")
        neighbor.style.animation = "none"
        neighbor.style.transform = `translateX(${-direction * container.getBoundingClientRect().width}px)`
        lead.append(neighbor)
        return neighbor
      }
      const settleSwipe = async (dx, advance) => {
        const image = activeImage
        if (!image) return
        if (reducedMotion() || !image.animate) {
          if (advance) { index = (index + (dx < 0 ? 1 : -1) + images.length) % images.length; setImage() }
          else { clearNeighbor(); renderTransform() }
          return
        }
        switching = true
        const direction = dx < 0 ? -1 : 1
        const distance = container.getBoundingClientRect().width
        const adjacent = prepareNeighbor(dx)
        const options = { duration: advance ? 240 : 180, easing: "cubic-bezier(.2,.8,.2,1)", fill: "forwards" }
        // Both images remain visible and travel together, without a fade or gap.
        const outgoing = image.animate([
          { transform: image.style.transform || "none" },
          { transform: `translateX(${advance ? direction * distance : 0}px)` },
        ], options)
        const incoming = adjacent.animate([
          { transform: adjacent.style.transform },
          { transform: `translateX(${advance ? 0 : -direction * distance}px)` },
        ], options)
        motion = outgoing; neighborMotion = incoming
        await Promise.all([outgoing.finished, incoming.finished].map(finished => finished.catch(() => {})))
        if (closing || removed || activeImage !== image || motion !== outgoing) return
        if (advance) {
          index = (index + (dx < 0 ? 1 : -1) + images.length) % images.length
          setImage(adjacent)
        } else {
          image.style.transform = "none"
          outgoing.cancel(); motion = undefined; clearNeighbor(); switching = false
        }
      }
      const point = touch => ({ x: touch.clientX, y: touch.clientY })
      const pinch = touches => {
        const a = point(touches[0]), b = point(touches[1])
        return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, distance: Math.hypot(a.x - b.x, a.y - b.y) }
      }
      const beginGesture = touches => {
        if (touches.length >= 2) {
          clearNeighbor()
          if (scale === 1) renderTransform()
          const center = pinch(touches), box = container.getBoundingClientRect()
          gesture = { mode: "pinch", ...center, scale, offsetX, offsetY, centerX: box.left + box.width / 2, centerY: box.top + box.height / 2 }
          suppressClickUntil = Date.now() + 500
        } else if (touches.length === 1) {
          gesture = { mode: scale > 1 ? "pan" : "swipe", ...point(touches[0]), offsetX, offsetY, dx: 0, dy: 0 }
        }
      }
      overlay.addEventListener("touchstart", event => {
        if (closing || switching || event.target.closest(".view-image-tools")) return
        beginGesture(event.touches)
        if (event.touches.length >= 2) event.preventDefault()
      }, { passive: false })
      overlay.addEventListener("touchmove", event => {
        if (!gesture || closing) return
        event.preventDefault()
        if (event.touches.length >= 2) {
          if (gesture.mode !== "pinch") beginGesture(event.touches)
          const center = pinch(event.touches), start = gesture
          scale = Math.max(1, Math.min(5, start.scale * center.distance / Math.max(1, start.distance)))
          const ratio = scale / start.scale
          offsetX = center.x - start.centerX - (start.x - start.centerX - start.offsetX) * ratio
          offsetY = center.y - start.centerY - (start.y - start.centerY - start.offsetY) * ratio
          renderTransform()
          suppressClickUntil = Date.now() + 500
        } else if (event.touches.length === 1 && gesture.mode !== "pinch") {
          const touch = point(event.touches[0])
          gesture.dx = touch.x - gesture.x; gesture.dy = touch.y - gesture.y
          if (Math.hypot(gesture.dx, gesture.dy) > 8) suppressClickUntil = Date.now() + 500
          if (gesture.mode === "pan") {
            offsetX = gesture.offsetX + gesture.dx; offsetY = gesture.offsetY + gesture.dy
            renderTransform()
          } else if (images.length > 1 && activeImage && !reducedMotion()) {
            activeImage.style.animation = "none"
            const delta = clamp(gesture.dx * .85, container.getBoundingClientRect().width)
            activeImage.style.transform = `translateX(${delta}px)`
            const adjacent = prepareNeighbor(gesture.dx)
            adjacent.style.transform = `translateX(${-neighborDirection * container.getBoundingClientRect().width + delta}px)`
          }
        }
      }, { passive: false })
      overlay.addEventListener("touchend", event => {
        if (!gesture || closing) return
        if (event.touches.length) {
          // Rebase the remaining finger after a pinch; never turn it into a swipe.
          beginGesture(event.touches)
          if (gesture && event.touches.length === 1) gesture.mode = "pan"
          return
        }
        const ended = gesture
        gesture = undefined
        if (ended.mode === "swipe" && images.length > 1 && ended.dx) {
          const advance = Math.abs(ended.dx) >= 50 && Math.abs(ended.dx) > Math.abs(ended.dy) * 1.3
          void settleSwipe(ended.dx, advance)
          return
        }
        if (scale <= 1.02) { scale = 1; offsetX = offsetY = 0; renderTransform() }
      })
      overlay.addEventListener("touchcancel", () => {
        const cancelled = gesture; gesture = undefined; suppressClickUntil = Date.now() + 500
        if (cancelled?.mode === "swipe" && cancelled.dx) void settleSwipe(cancelled.dx, false)
      })
      overlay.addEventListener("click", (event) => {
        event.stopPropagation()
        if(closing || switching || Date.now() < suppressClickUntil)return
        if (event.target.closest(".view-image-close")) close()
        if (event.target.closest(".view-image-tools__flip-prev")) { index = (index + images.length - 1) % images.length; setImage() }
        if (event.target.closest(".view-image-tools__flip-next")) { index = (index + 1) % images.length; setImage() }
      })
      overlay.addEventListener("cancel",event=>{event.preventDefault();close()})
      overlay.addEventListener("close",remove,{once:true})
      document.body.append(overlay)
      overlay.showModal()
      overlay.focus({preventScroll:true})
      document.dispatchEvent(new CustomEvent("view-image-open",{detail:{overlay}}))
      document.addEventListener("keydown", keyboard)
      setImage()
    },
  }
  window.ViewImage = ViewImage
})()
